#include <cstdio>
#include <iostream>

int main() {
    // Formatted output using printf from <cstdio>
    std::printf("Standard output via printf: %s\n", "Active");

    // Using literal characters and multiple specifiers
    int code = 200;
    std::printf("Status Code: %d (OK)\n", code);

    // Equivalent stream output via C++ std::cout
    std::cout << "Stream output via std::cout" << std::endl;

    return 0;
}

#include <cstdio>

int main() {
    // Fig. 9.2: Demonstrating integer conversion specifiers
    std::printf("%d\n", 455);
    std::printf("%i\n", 455); // i same as d in printf
    std::printf("%d\n", +455); // plus sign does not print
    std::printf("%d\n", -455); // minus sign prints
    std::printf("%hd\n", static_cast<short>(32000));
    std::printf("%ld\n", 2000000000L); // L suffix makes literal a long int
    std::printf("%o\n", 455); // octal
    std::printf("%u\n", 455);
    std::printf("%u\n", -455); // unsigned reinterpretation of negative number
    std::printf("%x\n", 455); // hexadecimal with lowercase letters
    std::printf("%X\n", 455); // hexadecimal with uppercase letters

    return 0;
}
